UPDATE media_shared_song SET verification=CASE WHEN expected_size IS NOT NULL AND (SELECT file_size FROM media_scan_song WHERE task_id=#{taskId} AND id=media_shared_song.song_id) IS NOT NULL AND expected_size<>(SELECT file_size FROM media_scan_song WHERE task_id=#{taskId} AND id=media_shared_song.song_id) THEN 'MISMATCH' ELSE 'PRESENT' END,verified_at=#{now} WHERE source_id=#{sourceId} AND song_id IN(SELECT id FROM media_scan_song WHERE task_id=#{taskId})
